#include <iostream>
#include <vector>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long a, c;
    if (!(std::cin >> a >> c)) {
        return 0;
    }

    std::vector<long long> x(105, 0);
    std::vector<long long> y(105, 0);
    int i = 0;

    for (i = 1; a + c > 0; ++i) {
        x[i] = a % 3;
        a /= 3;
        y[i] = c % 3;
        c /= 3;
    }

    long long b = 0;
    while (i > 1) {
        --i;
        b = b * 3 + ((y[i] - x[i] + 3) % 3);
    }

    std::cout << b << "\n";

    return 0;
}

